#include <iostream>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    ll all = 1;
    ll good = 0;

    for (int i = 1; i <= n; ++i) {
        good = (all * 20 + good * 7) % MOD;
        all = all * 27 % MOD;
    }

    cout << good << '\n';
    return 0;
}

#include <cstdio>

using ll = long long;

const ll MOD = 1000000007LL;

ll modPow(ll base, ll exponent) {
    ll result = 1;
    while (exponent > 0) {
        if (exponent & 1LL) {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exponent >>= 1LL;
    }
    return result;
}

int main() {
    ll n;
    if (scanf("%lld", &n) != 1) {
        return 0;
    }

    ll answer = (modPow(27, n) - modPow(7, n) + MOD) % MOD;
    printf("%lld\n", answer);
    return 0;
}

